import random
import math

def build_edges():
    edges = []
    for g in range(5):
        for i in range(3):
            for j in range(i+1, 3):
                edges.append((g*3+i, g*3+j))
    for g in range(4):
        for i in range(3):
            edges.append((g*3+i, (g+1)*3+i))
    return edges

edges = build_edges()
n_vertices = 15
n_edges = 27

def evaluate(labels):
    """Count number of distinct edge differences (want 27)"""
    diffs = set()
    for u, v in edges:
        d = abs(labels[u] - labels[v])
        diffs.add(d)
    return len(diffs)

def conflicts(labels):
    """Count conflicts (duplicate edge differences)"""
    diffs = []
    for u, v in edges:
        d = abs(labels[u] - labels[v])
        diffs.append(d)
    from collections import Counter
    c = Counter(diffs)
    return sum(v-1 for v in c.values() if v > 1)

best_solution = None
best_score = 0

# Try many random starts with local search
for trial in range(1000):
    # Random permutation of 15 values from 0..27
    available = list(range(28))
    random.shuffle(available)
    labels = available[:15]

    score = evaluate(labels)
    if score > best_score:
        best_score = score
        best_solution = labels[:]
        if best_score == 27:
            print(f"Found perfect solution at trial {trial}!")
            break

    # Local search: swap labels
    for _ in range(500):
        i = random.randint(0, 14)
        j = random.randint(0, 14)
        if i != j:
            labels[i], labels[j] = labels[j], labels[i]
            new_score = evaluate(labels)
            if new_score >= score:
                score = new_score
                if score > best_score:
                    best_score = score
                    best_solution = labels[:]
            else:
                labels[i], labels[j] = labels[j], labels[i]

        if score == 27:
            break

    if best_score == 27:
        break

print(f"Best score: {best_score}/27")
if best_solution:
    print(f"Best solution: {best_solution}")
